@Mod.EventBusSubscriber(modid="thaumcraft")
public final class UtilityProbe {
 public static final BlockPos P=new BlockPos(3648,205,8);public static volatile boolean ready,menuDone,framed;static int ticks,stage;static long due;static boolean cancel;static ServerPlayer actor;
 static void test(String name,Runnable task,List<String> errors){try{task.run();}catch(Throwable ex){errors.add(name+": "+ex);Thaumcraft.LOGGER.error("UTILITY_TEST_FAILURE_"+name,ex);}}
 static String mode(){return System.getProperty("thaumcraft.alchemyProbe","");}static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static <T> T create(ServerLevel l,BlockPos p,String name,Class<T> cls){l.setBlockAndUpdate(p.below(),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(p,UtilityContent.BLOCKS.get(name).get().defaultBlockState().setValue(UtilityBlock.FACING,Direction.DOWN));return cls.cast(l.getBlockEntity(p));}
 static thaumcraft.alchemy.AlchemyMachine jar(ServerLevel l,BlockPos p,String a,int n){l.setBlockAndUpdate(p,thaumcraft.alchemy.AlchemyContent.JAR.get().defaultBlockState());var j=(thaumcraft.alchemy.AlchemyMachine)l.getBlockEntity(p);if(n>0)check(j.insertEssence(a,n,false),"jar fixture");return j;}
 static Animal animal(ServerLevel l,String id,BlockPos p){var a=(Animal)net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getValue(net.minecraft.resources.Identifier.withDefaultNamespace(id)).create(l,EntitySpawnReason.COMMAND);a.setPos(Vec3.atBottomCenterOf(p));a.setNoAi(true);a.setPersistenceRequired();check(l.addFreshEntity(a),"animal fixture");return a;}
 static BlockPos dark(ServerLevel l,LampEntity lamp){for(int d=6;d<=15;d++){var p=lamp.getBlockPos().south(d);if(lamp.illuminate(p))return p;}throw new AssertionError("no dark visible target for arcane lamp");}
 static void lights(ServerLevel l){var legacy=P.north(8);l.setBlockAndUpdate(legacy,thaumcraft.infusion.InfusionContent.GLIMMER.get().defaultBlockState());((GlimmerEntity)l.getBlockEntity(legacy)).validateOwner();check(l.getBlockState(legacy).is(UtilityContent.GLIMMER.get()),"legacy unowned infusion light removed");var a=create(l,P.west(12),"lamp_arcane",LampEntity.class);var b=create(l,P.east(12),"lamp_arcane",LampEntity.class);var ap=dark(l,a);var bp=dark(l,b);l.setBlockAndUpdate(a.getBlockPos().east(3),Blocks.STONE.defaultBlockState());check(!LampEntity.visible(l,a.getBlockPos(),a.getBlockPos().east(6))&&!a.illuminate(a.getBlockPos().east(6)),"arcane lamp ignored wall");var old=b.identity();l.setBlockAndUpdate(a.getBlockPos().north(),Blocks.REDSTONE_BLOCK.defaultBlockState());a.serverTick();check(l.isEmptyBlock(ap)&&l.getBlockState(bp).is(UtilityContent.GLIMMER.get()),"power-off deleted other lamp lights");check(!a.illuminate(ap),"powered lamp created light");l.removeBlock(a.getBlockPos(),false);check(l.getBlockEntity(bp) instanceof GlimmerEntity glow&&glow.belongs(b.getBlockPos(),old),"other light ownership changed");Thaumcraft.LOGGER.info("UTILITY_LIGHTS_OK: real light blocks, line-of-sight wall, redstone cleanup and independent persistent ownership");}
 static void growth(ServerLevel l){var p=P.west(5);var lamp=create(l,p,"lamp_growth",LampEntity.class);var source=jar(l,p.below(),"herba",2);l.setBlockAndUpdate(p.north(),Blocks.REDSTONE_BLOCK.defaultBlockState());for(int n=0;n<20;n++)lamp.serverTick();check(source.total()==0&&lamp.charges()==20&&lamp.reserve(),"growth lamp did not pay 20+reserve");check(!lamp.insert("aqua",Direction.DOWN,false)&&!lamp.insert("herba",Direction.UP,true),"growth accepted wrong essence/side");var crop=p.south(2);l.setBlockAndUpdate(crop.below(),Blocks.FARMLAND.defaultBlockState().setValue(BlockStateProperties.MOISTURE,7));l.setBlockAndUpdate(crop,Blocks.WHEAT.defaultBlockState());l.setBlockAndUpdate(crop.above(),Blocks.LIGHT.defaultBlockState().setValue(net.minecraft.world.level.block.LightBlock.LEVEL,15));l.removeBlock(p.north(),false);check(source.insertEssence("herba",16,false),"growth test refill");l.getServer().clockManager().setTotalTicks(l.dimensionType().defaultClock().orElseThrow(),6000);for(int n=0;n<50000&&l.getBlockState(crop).getValue(BlockStateProperties.AGE_7)==0;n++)lamp.serverTick();check(l.getBlockState(crop).getValue(BlockStateProperties.AGE_7)>0&&lamp.charges()<20,"native crop did not actually grow with paid charge");l.setBlockAndUpdate(p.north(),Blocks.REDSTONE_BLOCK.defaultBlockState());int charge=lamp.charges();for(int n=0;n<200;n++)lamp.serverTick();check(lamp.charges()==charge,"redstone did not pause growth");Thaumcraft.LOGGER.info("UTILITY_GROWTH_OK: paid herba,20 charges plus reserve, native crop tick, side/aspect filtering and redstone pause");}
 static void fertility(ServerLevel l){var p=P.east(5);var lamp=create(l,p,"lamp_fertility",LampEntity.class);var source=jar(l,p.below(),"desiderium",5);l.setBlockAndUpdate(p.north(),Blocks.REDSTONE_BLOCK.defaultBlockState());for(int n=0;n<25;n++)lamp.serverTick();check(source.total()==0&&lamp.charges()==5,"fertility did not pay five essence");var first=animal(l,"cow",p.south(2));var second=animal(l,"cow",p.south(3));check(!lamp.breed(),"powered fertility worked");l.removeBlock(p.north(),false);check(lamp.breed()&&first.isInLove()&&second.isInLove()&&lamp.charges()==0,"fertility pair/cost");check(!lamp.breed(),"fertility borrowed charges");Thaumcraft.LOGGER.info("UTILITY_FERTILITY_OK: same-type adult pair, native love state, five paid units, no negative charge and redstone pause");}
 static void water(ServerLevel l){var p=P.south(10);var urn=create(l,p,"everfull_urn",WaterDevice.class);var aura=thaumcraft.aura.AuraManager.get(l,p);float before=aura.vis();int generated=urn.generate();check(generated>0&&generated<=100&&Math.abs((before-thaumcraft.aura.AuraManager.get(l,p).vis())-generated/1000F)<.001,"urn vis conversion");check(urn.handler().fill(new FluidStack(net.minecraft.world.level.material.Fluids.WATER,1000),IFluidHandler.FluidAction.EXECUTE)==0,"urn accepted external fill");int stored=urn.amount();check(urn.handler().drain(25,IFluidHandler.FluidAction.SIMULATE).getAmount()==25&&urn.amount()==stored,"urn drain simulation mutated");while(urn.amount()<1000)check(urn.generate()>0,"urn could not refill");var jar=jar(l,p.east(),"",0); // no fluid handler for ordinary jar; use crucible instead
 l.setBlockAndUpdate(p.east(),thaumcraft.alchemy.AlchemyContent.CRUCIBLE.get().defaultBlockState());var crucible=(thaumcraft.alchemy.AlchemyMachine)l.getBlockEntity(p.east());int start=urn.amount();check(urn.distribute()==25&&crucible.water.getFluidAmount()==25&&urn.amount()==start-25,"urn remote fluid payment");crucible.water.setFluid(new FluidStack(net.minecraft.world.level.material.Fluids.WATER,1000));check(urn.distribute()==0,"full recipient still took water");l.removeBlock(p.east(),false);l.setBlockAndUpdate(p.west(),Blocks.CAULDRON.defaultBlockState());check(urn.distribute()==333&&l.getBlockState(p.west()).is(Blocks.WATER_CAULDRON),"urn native cauldron fill");
 var spa=create(l,P.south(4),"spa",WaterDevice.class);for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++){var q=spa.getBlockPos().offset(x,0,z);if(!q.equals(spa.getBlockPos()))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());if(Math.abs(x)==3||Math.abs(z)==3)l.setBlockAndUpdate(q.above(),Blocks.GLASS.defaultBlockState());}var fluid=new FluidStack(net.minecraft.world.level.material.Fluids.WATER,2500);check(spa.handler().fill(fluid,IFluidHandler.FluidAction.SIMULATE)==2500&&spa.amount()==0,"spa fill simulation mutated");check(spa.handler().fill(fluid,IFluidHandler.FluidAction.EXECUTE)==2500,"spa tank fill");spa.inventory.setItem(0,new ItemStack(thaumcraft.taint.TaintContent.SALTS.get(),2));l.setBlockAndUpdate(spa.getBlockPos().above(),Blocks.STONE.defaultBlockState());check(!spa.placeBath()&&spa.amount()==2500&&spa.inventory.getItem(0).getCount()==2,"blocked bath paid ingredients");l.removeBlock(spa.getBlockPos().above(),false);net.minecraftforge.event.level.BlockEvent.FluidPlaceBlockEvent.BUS.addListener(e->cancel&&e.getLiquidPos().equals(spa.getBlockPos()));cancel=true;check(!spa.placeBath()&&spa.amount()==2500&&spa.inventory.getItem(0).getCount()==2,"cancelled bath paid ingredients");cancel=false;check(spa.placeBath()&&spa.amount()==1500&&spa.inventory.getItem(0).getCount()==1&&l.getBlockState(spa.getBlockPos().above()).is(thaumcraft.taint.TaintContent.PURE.block.get()),"mixed bath cost/source");spa.toggle();l.removeBlock(spa.getBlockPos().above(),false);check(spa.placeBath()&&spa.amount()==500&&spa.inventory.getItem(0).getCount()==1&&l.getFluidState(spa.getBlockPos().above()).isSource(),"plain fluid bath consumed salts");var nether=l.getServer().getLevel(net.minecraft.world.level.Level.NETHER);nether.setChunkForced(P.getX()>>4,P.getZ()>>4,true);var np=new BlockPos(P.getX(),110,P.getZ());nether.setBlockAndUpdate(np.above(),Blocks.AIR.defaultBlockState());var hell=create(nether,np,"spa",WaterDevice.class);hell.handler().fill(new FluidStack(net.minecraft.world.level.material.Fluids.WATER,2000),IFluidHandler.FluidAction.EXECUTE);hell.inventory.setItem(0,new ItemStack(thaumcraft.taint.TaintContent.SALTS.get()));check(hell.placeBath()&&hell.amount()==1000,"Nether rejected magical purifying bath");hell.toggle();nether.removeBlock(np.above(),false);check(!hell.placeBath()&&hell.amount()==1000,"Nether placed ordinary water or charged failed placement");Thaumcraft.LOGGER.info("UTILITY_NETHER_OK: magical bath works; ordinary water blocked without payment in evaporating environment");Thaumcraft.LOGGER.info("UTILITY_WATER_OK: vis-paid urn, simulated drains/fills, remote fluid conservation, full target, native cauldron, bath blockage/cancellation and exact salts/fluid payments");}
 static ItemStack potion(ServerLevel l){var registry=l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.POTION);var holder=registry.getOrThrow(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.POTION,net.minecraft.resources.Identifier.withDefaultNamespace("swiftness")));return PotionContents.createItemStack(Items.POTION,holder);}
 static void sprayer(ServerLevel l){var p=P.north(5);var spray=create(l,p,"potion_sprayer",SprayerEntity.class);l.setBlockAndUpdate(p,spray.getBlockState().setValue(UtilityBlock.FACING,Direction.SOUTH));var potion=potion(l);spray.inventory.setItem(0,potion);check(!spray.recipe().isEmpty()&&spray.recipe().size()<=10&&!spray.recipe().equals(Map.of("praecantatio",5,"alkimia",5)),"potion recipe empty");for(var entry:spray.recipe().entrySet())for(int n=0;n<entry.getValue();n++){check(!spray.insert(entry.getKey(),Direction.SOUTH,true),"front accepted essence");var before=spray.progress();check(spray.insert(entry.getKey(),Direction.DOWN,true)&&spray.progress().equals(before),"sprayer simulation mutated");check(spray.insert(entry.getKey(),Direction.DOWN,false),"sprayer recipe rejected required essence");}for(int n=0;n<5;n++)spray.serverTick();check(spray.charges()==1&&spray.progress().isEmpty()&&ItemStack.isSameItemSameComponents(potion,spray.inventory.getItem(0)),"charge consumed potion or failed exact recipe");var target=animal(l,"pig",p.south(2));l.setBlockAndUpdate(p.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());spray.serverTick();check(spray.charges()==0&&target.hasEffect(net.minecraft.world.effect.MobEffects.SPEED),"redstone spray/effect");spray.serverTick();check(spray.charges()==0,"held redstone retriggered");l.setBlockAndUpdate(p.east(),Blocks.AIR.defaultBlockState());spray.serverTick();for(var entry:spray.recipe().entrySet())for(int n=0;n<entry.getValue();n++)check(spray.insert(entry.getKey(),Direction.DOWN,false),"second charge");for(int n=0;n<5;n++)spray.serverTick();check(spray.charges()==1,"second charge not paid");spray.inventory.setItem(0,ItemStack.EMPTY);check(spray.charges()==0&&spray.progress().isEmpty(),"pattern removal kept old charges");spray.inventory.setItem(0,potion);for(var entry:spray.recipe().entrySet())for(int n=0;n<entry.getValue();n++)check(spray.insert(entry.getKey(),Direction.DOWN,false),"restart charge payment");for(int n=0;n<5;n++)spray.serverTick();l.setBlockAndUpdate(p.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());spray.serverTick(); // latch before saving; refill while signal remains high
 for(var entry:spray.recipe().entrySet())for(int n=0;n<entry.getValue();n++)check(spray.insert(entry.getKey(),Direction.DOWN,false),"latched refill");for(int n=0;n<5;n++)spray.serverTick();check(spray.charges()==1,"held signal consumed newly filled charge");Thaumcraft.LOGGER.info("UTILITY_SPRAYER_OK: native brewing reagent costs, side/aspect and simulation checks, exact paid charge, retained pattern, real potion effect, single redstone edge and template reset");}
 static void unknown(ServerLevel l){var spa=create(l,P.east(10).north(5),"spa",WaterDevice.class);var tag=spa.saveWithFullMetadata(l.registryAccess());tag.getCompoundOrEmpty("utility").putInt("version",2);var data=net.minecraft.world.item.component.TypedEntityData.of(UtilityContent.WATER.get(),tag);check(data.loadInto(spa,l.registryAccess())&&!spa.supported()&&spa.handler().fill(new FluidStack(net.minecraft.world.level.material.Fluids.WATER,1000),IFluidHandler.FluidAction.EXECUTE)==0,"future water state not disabled");var drops=Block.getDrops(spa.getBlockState(),l,spa.getBlockPos(),spa);check(drops.size()==1&&drops.getFirst().get(DataComponents.BLOCK_ENTITY_DATA).copyTagWithoutId().getCompoundOrEmpty("utility").getIntOr("version",0)==2,"future state not preserved on block item");Thaumcraft.LOGGER.info("UTILITY_UNKNOWN_OK: future format disabled and preserved on native dropped block item");}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!mode().startsWith("utility-"))return;var l=e.server().overworld();if(++ticks<80)return;if(stage==99){if(mode().equals("utility-client")&&ready&&menuDone&&!framed){actor.teleportTo(l,P.getX()+.5,P.getY()+5,P.getZ()+19.5,Set.of(),180,30,true);framed=true;Thaumcraft.LOGGER.info("UTILITY_WORLD_FRAMED: completed native menu checks; overview of six devices");}return;}if(stage==0){l.getServer().clockManager().setTotalTicks(l.dimensionType().defaultClock().orElseThrow(),6000);for(int x=226;x<=230;x++)for(int z=-2;z<=2;z++)l.setChunkForced(x,z,true);due=l.getGameTime()+80;stage=1;return;}if(l.getGameTime()<due)return;if(mode().equals("utility-read")){var spray=(SprayerEntity)l.getBlockEntity(P.north(5));check(spray.charges()==1&&spray.inventory.getItem(0).has(DataComponents.POTION_CONTENTS),"restart lost sprayer paid charge/pattern or replayed edge");var growth=(LampEntity)l.getBlockEntity(P.west(5));check(growth.supported()&&growth.reserve()&&growth.charges()>0,"restart lost growth reserve");var b=(LampEntity)l.getBlockEntity(P.east(12));var saved=LampEntity.CODEC.parse(net.minecraft.nbt.NbtOps.INSTANCE,b.saveWithoutMetadata(l.registryAccess()).getCompoundOrEmpty("utility")).getOrThrow();check(saved.lights().stream().anyMatch(pos->l.hasChunkAt(pos)&&l.getBlockEntity(pos) instanceof GlimmerEntity glow&&glow.belongs(b.getBlockPos(),b.identity())),"restart lost owned light");var future=(WaterDevice)l.getBlockEntity(P.east(10).north(5));check(!future.supported(),"restart reset future state");Thaumcraft.LOGGER.info("UTILITY_RESTART_OK: native paid charges/potion, redstone edge, growth reserve, owned light and unknown state survived second JVM");stage=99;e.server().halt(false);return;}
 if(mode().equals("utility-client")&&e.server().getPlayerList().getPlayers().isEmpty())return;if(stage==1){for(var q:BlockPos.betweenClosed(P.offset(-18,-2,-12),P.offset(18,5,15)))l.setBlockAndUpdate(q,q.getY()==P.getY()-2?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());l.getEntitiesOfClass(Entity.class,new AABB(P).inflate(25),en->!(en instanceof net.minecraft.world.entity.player.Player)).forEach(Entity::discard);due=l.getGameTime()+40;stage=2;return;}stage=99;var errors=new ArrayList<String>();test("lights",()->lights(l),errors);test("growth",()->growth(l),errors);test("fertility",()->fertility(l),errors);test("water",()->water(l),errors);test("sprayer",()->sprayer(l),errors);test("unknown",()->unknown(l),errors);check(errors.isEmpty(),errors.toString());if(mode().equals("utility-client")){actor=e.server().getPlayerList().getPlayers().getFirst();actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.getInventory().clearContent();actor.teleportTo(l,P.getX()+.5,P.getY()+3,P.getZ()+7.5,Set.of(),180,50.4F,true);actor.getAbilities().flying=true;actor.onUpdateAbilities();ready=true;Thaumcraft.LOGGER.info("UTILITY_CLIENT_READY: six real utility mechanics and native effects in world");return;}e.server().halt(false);}
}
